import{_ as o,o as t,c as d,a2 as a}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"搜索语法","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/search-syntax.md","filePath":"zh-CN/user-guide/search-syntax.md","lastUpdated":1785993908000}'),c={name:"zh-CN/user-guide/search-syntax.md"};function s(r,e,n,i,l,p){return t(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="搜索语法" tabindex="-1">搜索语法 <a class="header-anchor" href="#搜索语法" aria-label="Permalink to &quot;搜索语法&quot;">​</a></h1><p>Lertaro 的搜索框支持的不只是普通输入。下面每一种操作符都可以和普通模糊词混合使用在同一条查询里。</p><h2 id="模糊匹配-默认" tabindex="-1">模糊匹配(默认) <a class="header-anchor" href="#模糊匹配-默认" aria-label="Permalink to &quot;模糊匹配(默认)&quot;">​</a></h2><p>输入名称的任意一部分即可命中，只要字符按顺序出现在文件/文件夹名的任意位置即可，不需要输入连续的子串：</p><table tabindex="0"><thead><tr><th>输入</th><th>命中</th></tr></thead><tbody><tr><td><code>swlst</code></td><td><code>Lertaro.exe</code></td></tr><tr><td><code>report</code></td><td><code>Q3-report-final.docx</code></td></tr></tbody></table><p>在<strong>设置 → 通用 → 系统 → 启用模糊匹配</strong>里关掉这个开关后，普通查询词(不带任何操作符)就必须作为连续子串出现——<code>abc</code> 不再匹配 <code>a-b-c</code>。下面表格里的每一种操作符不受这个开关影响，行为完全一样；开关只改变普通词本身的要求。<code>&#39;</code> 操作符不管这个开关开没开，都会对单个词翻转精确性，所以你可以在一条整体走精确匹配的查询里塞进一个模糊词，或者反过来，而不用去改这个全局开关。</p><h2 id="多个词" tabindex="-1">多个词 <a class="header-anchor" href="#多个词" aria-label="Permalink to &quot;多个词&quot;">​</a></h2><p>用空格分隔多个词。每个词都会进一步缩小结果范围——但<strong>不要求</strong>这些词按你输入的顺序出现：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report final</span></span></code></pre></div><p><code>final-Q3-report.docx</code> 和 <code>Q3-report-final.docx</code> 都能匹配。</p><h2 id="大小写敏感" tabindex="-1">大小写敏感 <a class="header-anchor" href="#大小写敏感" aria-label="Permalink to &quot;大小写敏感&quot;">​</a></h2><ul><li><strong>全部小写</strong>的查询不区分大小写：<code>myfile</code> 可以匹配 <code>MyFile</code>、<code>MYFILE</code> 等。</li><li>只要查询里<strong>出现任意大写字母</strong>，该词就变为大小写敏感：<code>MyFile</code> 只匹配 <code>MyFile</code>，不匹配 <code>myfile</code>。</li></ul><h2 id="操作符" tabindex="-1">操作符 <a class="header-anchor" href="#操作符" aria-label="Permalink to &quot;操作符&quot;">​</a></h2><table tabindex="0"><thead><tr><th>前缀/后缀</th><th>示例</th><th>效果</th></tr></thead><tbody><tr><td>(无)</td><td><code>report</code></td><td>默认的模糊匹配，命中名称中任意位置。</td></tr><tr><td><code>!</code></td><td><code>!temp</code></td><td><strong>排除</strong>——过滤掉名称中含有 <code>temp</code> 这个精确子串的结果(这一项不走模糊匹配)。</td></tr><tr><td><code>&#39;</code></td><td><code>&#39;report</code></td><td>对这一个词<strong>翻转精确性</strong>——模糊匹配开启(默认)时变成精确子串匹配；在设置里关闭模糊匹配后，这个词反而会变回模糊匹配。</td></tr><tr><td><code>&#39;...&#39;</code></td><td><code>&#39;final report&#39;</code></td><td>精确匹配，且要求词边界(不会命中被包在更长单词内部的情况)。</td></tr><tr><td><code>^</code></td><td><code>^IMG</code></td><td><strong>前缀</strong>匹配——名称必须以 <code>IMG</code> 开头。</td></tr><tr><td><code>$</code></td><td><code>.pdf$</code></td><td><strong>后缀</strong>匹配——名称必须以 <code>.pdf</code> 结尾。</td></tr><tr><td><code>^...$</code></td><td><code>^readme.md$</code></td><td><strong>完全相等</strong>——名称必须正好是 <code>readme.md</code>。仅当两者包住<strong>同一个</strong>词时成立；分别写在不同的词上时，它们各自仍然只是前缀和后缀过滤。</td></tr><tr><td><code>|</code></td><td><code>report | summary</code></td><td><strong>或</strong>——匹配管道符任意一侧。</td></tr></tbody></table><p>这些操作符可以自由组合，例如 <code>^IMG !.png$ 2024</code> 可以找到以 <code>IMG</code> 开头、包含 2024、但<strong>不是</strong> PNG 的文件。</p><p>&quot;或&quot;查询里，一个结果名称中<strong>每一个</strong>真正匹配到的词都会高亮，不只是最先匹配到的那一个——所以 <code>report | summary</code> 如果结果名称里同时包含这两个词，两个词都会被高亮。</p><h2 id="粘贴多行文本" tabindex="-1">粘贴多行文本 <a class="header-anchor" href="#粘贴多行文本" aria-label="Permalink to &quot;粘贴多行文本&quot;">​</a></h2><p>粘贴包含多行的文本——比如从表格或文本文件里一行一个文件名复制过来的内容——Lertaro 会自动把它们折叠成一条 OR 查询，而不是原样粘贴：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>123</span></span>
<span class="line"><span>456</span></span>
<span class="line"><span>678</span></span></code></pre></div><p>粘贴进去会变成 <code>123 | 456 | 678</code>，同时匹配这三者中的任意一个。空行会被跳过。普通的单行粘贴不受影响。</p><h2 id="指定盘符" tabindex="-1">指定盘符 <a class="header-anchor" href="#指定盘符" aria-label="Permalink to &quot;指定盘符&quot;">​</a></h2><p>在查询开头输入盘符加冒号，即可把搜索范围限定在该盘，后面照常输入关键词：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d: report</span></span></code></pre></div><p>只在 <code>D:</code> 盘搜索。</p><p>空格可以省略：<code>d:report</code> 和 <code>d: report</code> 含义相同。</p><h2 id="路径模式" tabindex="-1">路径模式 <a class="header-anchor" href="#路径模式" aria-label="Permalink to &quot;路径模式&quot;">​</a></h2><p>如果查询里包含路径分隔符(<code>\\</code> 或 <code>/</code>)，Lertaro 会切换到路径模式，按完整路径而不仅仅是名称来匹配——适合直接跳转到已知的文件夹：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>D:\\Projects\\Lertaro</span></span></code></pre></div><p>以分隔符结尾(<code>D:\\Projects\\</code>)则会搜索该文件夹<strong>内部</strong>的内容。</p><h2 id="按文件夹名与通配符二次过滤-query-tokens" tabindex="-1">按文件夹名与通配符二次过滤 (Query Tokens) <a class="header-anchor" href="#按文件夹名与通配符二次过滤-query-tokens" aria-label="Permalink to &quot;按文件夹名与通配符二次过滤 (Query Tokens)&quot;">​</a></h2><p>Lertaro 支持在主搜索关键词后面使用查询标记（Query Tokens，默认通过前缀 <code>:</code> 或专用触发前缀引用）对主检索结果进行二次链式过滤：</p><ul><li><strong>通配符二次过滤（<code>:?&lt;通配符表达式&gt;</code> 或 <code>?&lt;通配符表达式&gt;</code>）</strong>：使用 Windows 标准通配符语法（<code>?</code> 匹配任意单字符，<code>*</code> 匹配任意多字符）对主搜索结果进行二次精确定位。例如输入 <code>mp4 :?(2026???????????)</code> 或 <code>mp4 ?(2026???????????)</code>，可精确检索出名字中带 2026 及 11 位日期时间戳的重复视频。支持用 <code>|</code> 或 <code>;</code> 分隔多个表达式组成 OR 条件（例如 <code>?(2026*)|*.png</code>）。</li><li><strong>路径匹配（<code>::&lt;路径表达式&gt;</code>）</strong>：要求结果名称或上级文件夹匹配指定文本（如 <code>1080 ::wallpapers</code> 或 <code>report ::2024</code>）。</li><li><strong>自定义分类（<code>:@&lt;关键字&gt;</code>）</strong>：套用内置或自定义的扩展名过滤规则（如 <code>:@doc</code> 或 <code>:@video</code>）。</li></ul><h2 id="词描述的是文件夹-不是文件本身" tabindex="-1">词描述的是文件夹，不是文件本身 <a class="header-anchor" href="#词描述的是文件夹-不是文件本身" aria-label="Permalink to &quot;词描述的是文件夹，不是文件本身&quot;">​</a></h2><p>如果按文件/文件夹名匹配没能填满结果，Lertaro 会自动补上一批，额外允许词命中上级文件夹——不需要任何特殊语法：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d01j dcj</span></span></code></pre></div><p>即使 <code>dcj</code> 从未出现在文件自己的名字里，也能找到一个名为 <code>d01j</code>、位于名为(或别名为)<code>dcj</code> 的文件夹下的文件。这只是用文件上层的文件夹名，补全查询里没被文件名本身覆盖的部分——至少要有一个词仍然命中文件名本身，而且只在按名称的普通搜索没填满结果时才会触发；补上来的结果一律排在它们后面，不会与之混排，所以永远不会顶掉或打乱普通搜索本来就能找到的结果。上级文件夹的匹配方式和文件名完全一样，所以拼音在这里同样能命中中文文件夹名。</p><h2 id="单次搜索绕过排除规则" tabindex="-1">单次搜索绕过排除规则 <a class="header-anchor" href="#单次搜索绕过排除规则" aria-label="Permalink to &quot;单次搜索绕过排除规则&quot;">​</a></h2><p>在查询开头加 <code>*</code>，可以让这一次搜索绕过你自己设置的<a href="./settings/index-drives.html#排除规则">排除规则</a>—— <code>ExcludedPaths</code>、忽略的 glob、忽略的正则——而不需要改动设置本身：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*node_modules</span></span></code></pre></div><p><code>*</code> 本身会在匹配之前被剥离掉，不会被当成搜索文字的一部分。这只能找回<strong>已经被索引过</strong>的结果；一个从未被索引过的文件夹(网络盘或 WSL 上被排除的文件夹)依然不会出现。隐藏/系统文件不受影响，始终照常过滤——<code>*</code> 只影响你自己配置的排除规则。只打 <code>*</code>、后面还没打内容时，会显示&quot;继续输入以搜索&quot;这样的提示，而不是&quot;无搜索结果&quot;，因为这时候实际上还没有真正搜索过。</p><h2 id="结果类型触发符" tabindex="-1">结果类型触发符 <a class="header-anchor" href="#结果类型触发符" aria-label="Permalink to &quot;结果类型触发符&quot;">​</a></h2><p>可选功能，默认没有配置，需要自己指定字符。如果你在<strong>设置 → 通用 → 快速搜索窗口 → 结果类型优先级</strong>里给某个结果类型配了触发符，把这个字符打在快速窗口查询的最前面，就只会显示这个类型的结果——应用程序、系统设置、某一个具体的文件过滤器、某个插件自己的条目，或者纯文件——其他类型全部隐藏：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>;vs</span></span></code></pre></div><p>如果 <code>;</code> 是应用程序这个类型配置的触发符，这样搜就只会在应用程序里找&quot;Visual Studio&quot;，不管其他类型的文本本来匹配得多好都不参与竞争。只打触发符、后面还没打内容时，会显示一个说明具体类型的提示，而不是&quot;无搜索结果&quot;。历史记录和收藏夹不受影响——不管有没有触发符，它们始终排最前。默认没有配置任何触发符，去<a href="./settings/general.html#快速搜索窗口">通用设置</a>里可以自行设置。</p><h2 id="中文文件名-拼音别名" tabindex="-1">中文文件名:拼音别名 <a class="header-anchor" href="#中文文件名-拼音别名" aria-label="Permalink to &quot;中文文件名:拼音别名&quot;">​</a></h2><p>包含中文字符的文件名会自动支持拼音搜索，无需任何配置：</p><ul><li><strong>全拼</strong>:输入 <code>chongqing</code> 可以匹配名为&quot;重庆&quot;的文件。</li><li><strong>首字母</strong>:输入 <code>cq</code> 同样可以匹配&quot;重庆&quot;(每个音节的首字母)。</li><li><strong>多音字</strong>(有多种读音的汉字)会为每种常见读音都生成别名，所以不管你想到的是哪种读音，通常都能命中。</li></ul><p>这是由内置的别名插件负责实现的——如果想确认它是否启用，可以到<strong>设置 → 插件</strong>里查看。</p><h2 id="西班牙语文件名-重音别名" tabindex="-1">西班牙语文件名：重音别名 <a class="header-anchor" href="#西班牙语文件名-重音别名" aria-label="Permalink to &quot;西班牙语文件名：重音别名&quot;">​</a></h2><p>包含西班牙语重音字符（<code>á</code>、<code>é</code>、<code>í</code>、<code>ó</code>、<code>ú</code>、<code>ü</code>、<code>ñ</code>）的文件名可自动通过标准无重音 ASCII 字母进行搜索，无需额外配置：输入 <code>cancion</code> 可匹配 <code>Canción.mp3</code>，输入 <code>nino</code> 可匹配 <code>Niño.txt</code>，输入 <code>ciguena</code> 可匹配 <code>Cigüeña.png</code>。匹配的字符（包括原文件名中的重音字符）将保持精准高亮。该功能由内置的 <code>SpanishAlias</code> 插件提供，可在 <strong>设置 → 插件</strong> 中查看与管理。</p><h2 id="收藏夹-而非自定义别名" tabindex="-1">收藏夹，而非自定义别名 <a class="header-anchor" href="#收藏夹-而非自定义别名" aria-label="Permalink to &quot;收藏夹，而非自定义别名&quot;">​</a></h2><p>Lertaro 没有一个通用的&quot;自定义别名/宏&quot;系统。最接近的等价功能是<a href="./settings/favorites.html">收藏夹</a>：把文件夹、文件或网址收藏为一个自定义显示名，之后就能用这个名字搜到它(结果里会带 ★ 标记)。如果你想要的其实是&quot;自定义一个关键词来启动某个程序&quot;，可以看看<a href="./instant-answers.html#自定义命令">自定义命令</a>。</p>`,52)])])}const g=o(c,[["render",s]]);export{u as __pageData,g as default};
